// Map each ACTIVE adset's optimization event to its pixel, so we can flag the events
// campaigns actually bid on. Standard enums map to pixel event names; OTHER uses the
// custom event string. (Custom conversions referenced only by id are not resolved here.)
const ENUM = { PURCHASE:'Purchase', LEAD:'Lead', INITIATED_CHECKOUT:'InitiateCheckout', COMPLETE_REGISTRATION:'CompleteRegistration', ADD_TO_CART:'AddToCart', CONTACT:'Contact', SUBSCRIBE:'Subscribe', ADD_PAYMENT_INFO:'AddPaymentInfo', SCHEDULE:'Schedule', START_TRIAL:'StartTrial', SUBMIT_APPLICATION:'SubmitApplication', VIEW_CONTENT:'ViewContent', SEARCH:'Search', DONATE:'Donate' };
const adsets = ($json.data) || [];
const optMap = {};
for (const a of adsets) {
  if (a.effective_status !== 'ACTIVE') continue;
  const po = a.promoted_object || {};
  if (!po.pixel_id) continue;
  const ev = po.custom_event_str || ENUM[po.custom_event_type] || (po.custom_event_type && po.custom_event_type !== 'OTHER' ? po.custom_event_type : null);
  if (!ev) continue;
  (optMap[po.pixel_id] = optMap[po.pixel_id] || []);
  if (!optMap[po.pixel_id].includes(ev)) optMap[po.pixel_id].push(ev);
}
return [{ json: { optMap } }];

// Pick which pixels to audit. DEFAULT = only pixels your ACTIVE campaigns optimize on
// (that is where dedup costs money, and it keeps Graph calls low to avoid rate limits).
// Optimization-target pixels first, then fill with other recently-active pixels up to
// PIXEL_LIMIT. DATASET_IDS overrides everything.
const cfg = $('Set config (account & thresholds)').first().json;
const ACTIVE_DAYS = Number(cfg.ACTIVE_DAYS) || 14;
const PIXEL_LIMIT = Number(cfg.PIXEL_LIMIT) || 15;
const DATASET_IDS = String(cfg.DATASET_IDS || '').split(',').map((s) => s.trim()).filter(Boolean);
const optMap = ($('Extract optimization targets').first().json.optMap) || {};
const list = ($('List account pixels').first().json.data) || [];
const byId = {}; list.forEach((p) => { byId[String(p.id)] = p.name; });
const now = Date.now();
const recent = list.filter((p) => p.last_fired_time && (now - new Date(p.last_fired_time).getTime()) < ACTIVE_DAYS * 864e5).map((p) => String(p.id));
let ids;
if (DATASET_IDS.length) ids = DATASET_IDS;                       // explicit override
else {
  const optIds = Object.keys(optMap).filter((id) => byId[id]);  // pixels campaigns bid on
  ids = optIds.length ? optIds : recent;                        // ONLY the money pixels if any exist
}
ids = ids.slice(0, PIXEL_LIMIT);
return ids.map((id) => ({ json: { pixel_id: id, name: byId[id] || id, is_opt_pixel: !!optMap[id] } }));

// Parse the browser-vs-server split and carry the pixel id/name forward.
const px = $('Select active pixels').all();
return $input.all().map((it, i) => {
  const data = (it.json.data) || [];
  let server = 0, browser = 0;
  for (const w of data) for (const r of (w.data || [])) { const c = Number(r.count) || 0; if (r.value === 'SERVER') server += c; else if (r.value === 'BROWSER') browser += c; }
  return { json: { pixel_id: px[i].json.pixel_id, name: px[i].json.name, server, browser } };
});

// Combine source split (carried) + per-event counts (input) + optimization targets.
// Flag pixels where an OPTIMIZATION event is dual-source - that is the costly case.
const cfg = $('Set config (account & thresholds)').first().json;
const MIN_EVENTS = Number(cfg.MIN_EVENTS) || 50;
const NON_CONV = new Set(['PageView', 'ViewContent', 'SubscribedButtonClick', 'Microdata']);
const optMap = ($('Extract optimization targets').first().json.optMap) || {};
const carried = $('Carry pixel id + source split').all().map((i) => i.json);
const evtResp = $input.all().map((i) => i.json);
const out = [];
for (let i = 0; i < carried.length; i++) {
  const { pixel_id, name, server, browser } = carried[i];
  const total = server + browser;
  if (total < MIN_EVENTS) continue;
  const server_pct = Math.round((100 * server) / total);
  const agg = {};
  for (const w of ((evtResp[i] || {}).data || [])) for (const r of (w.data || [])) agg[r.value] = (agg[r.value] || 0) + (Number(r.count) || 0);
  const optNames = optMap[pixel_id] || [];
  const events = Object.entries(agg).map(([n, c]) => ({ name: n, count: c, is_conversion: !NON_CONV.has(n), is_optimization: optNames.includes(n) }))
    .sort((a, b) => (b.is_optimization - a.is_optimization) || b.count - a.count);
  const conv_events = events.filter((e) => e.is_conversion).slice(0, 6);
  const opt_events = optNames;
  let status, risk;
  if (server_pct < 5) { status = 'browser_only'; risk = 'high'; }
  else if (server_pct > 95) { status = 'server_only'; risk = 'ok'; }
  else { status = 'dual_verify_dedup'; risk = 'verify'; }
  // Priority: an optimization event on a non-ok pixel is the one that costs money.
  const priority = (risk === 'ok' ? 0 : 10) + (opt_events.length ? 5 : 0) + Math.min(server_pct === 0 ? 0 : 4, 4);
  out.push({ pixel_id, name, server, browser, total, server_pct, pageview: agg['PageView'] || 0, opt_events, conv_events, status, risk, priority });
}
out.sort((a, b) => b.priority - a.priority || b.total - a.total);
return out.map((o) => ({ json: o }));

// Ask Claude for a next step per flagged pixel, focused on the OPTIMIZATION events.
// Never assert confirmed double-counting; never call PageView a conversion.
const pixels = $input.all().map((i) => i.json);
const flagged = pixels.filter((p) => p.risk === 'high' || p.risk === 'verify');
const system = 'You are a Meta server-side tracking specialist. Each pixel has browser vs server totals ACROSS ALL EVENTS (mostly PageView), its top conversion events, and opt_events = the events its ACTIVE campaigns optimize toward. dual_verify_dedup = both browser and server fire; IF they do not share an event_id, Meta double-counts. You CANNOT confirm double-counting from counts, so always say VERIFY. browser_only = CAPI effectively off. PRIORITISE the opt_events - a double-counted optimization event wastes ad spend. Never call PageView a conversion. For each pixel: one-line risk and one concrete next step naming the optimization event(s) to verify a shared event_id on (or add CAPI). Terse. Return ONLY JSON.';
const user = 'Pixels:\n' + JSON.stringify(flagged) + '\n\nReturn JSON exactly: {"summary":"one sentence, do NOT claim confirmed double-counting","pixels":[{"name":"","status":"","action":""}]}';
const body = { model: 'claude-haiku-4-5', max_tokens: 1200, system, messages: [{ role: 'user', content: user }] };
return [{ json: { body } }];

// Print the audit: optimization events first, then source split + top conversions + verdict.
const ctx = $('Classify dedup risk per pixel').all().map((i) => i.json);
const raw = ($json.content && $json.content[0] && $json.content[0].text) || '{}';
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
let parsed = { summary: '', pixels: [] };
try { parsed = JSON.parse(raw.slice(s, e + 1)); } catch (err) {}
const actOf = {}; (parsed.pixels || []).forEach((p) => { actOf[p.name] = p; });
const label = { dual_verify_dedup: 'VERIFY DEDUP', browser_only: 'NO CAPI', server_only: 'ok' };
const out = [];
out.push('');
out.push('==========================================================');
out.push('  META DEDUP / OPTIMIZATION-EVENT AUDIT  |  nocode.expert');
out.push('==========================================================');
out.push(parsed.summary || '');
out.push('Pixels checked: ' + ctx.length);
out.push('');
for (const p of ctx) {
  const flag = p.risk !== 'ok' ? '  <-- ' + label[p.status] : '';
  const optFlag = (p.opt_events.length && p.risk !== 'ok') ? '  [OPTIMIZED EVENT AT RISK]' : '';
  out.push('[' + String(p.server_pct).padStart(3) + '% server] ' + p.name + flag + optFlag);
  if (p.opt_events.length) out.push('        campaigns optimize toward: ' + p.opt_events.join(', '));
  out.push('        server ' + p.server + ' | browser ' + p.browser + '  (' + p.pageview + ' PageView of ' + p.total + ' total)');
  const conv = p.conv_events.map((c) => c.name + ' ' + c.count + (c.is_optimization ? '*' : '')).join(', ');
  if (conv) out.push('        conversion events: ' + conv);
  const a = actOf[p.name];
  if (a && a.action) out.push('        ACTION: ' + a.action);
}
out.push('==========================================================');
out.push('* = event your active campaigns optimize toward');
console.log(out.join('\n'));
return [{ json: { audit: ctx, summary: parsed.summary } }];
